import React, { useState, useEffect } from 'react';

function FloatingSidebar({ sidebarClosed, setSidebarClosed, pastOrders, setCurrentPage, addToCart, showToast }) {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [activeMood, setActiveMood] = useState('');

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const toggleSidebar = () => {
    setSidebarClosed(!sidebarClosed);
  };

  const showOrderHistory = () => {
    setCurrentPage('profile');
    setSidebarClosed(true);
  };

  const quickAddToCart = (itemId) => {
    addToCart(itemId, 1);
  };

  const setMood = (mood) => {
    setActiveMood(mood);
    const moodMessages = {
      happy: 'Great mood! Try our special Veg Thali!',
      hungry: 'Super hungry? Go for our filling Pav Bhaji!',
      tired: 'Need energy? A hot Chai will refresh you!',
      excited: 'Exciting! Try our crispy Samosa!'
    };
    showToast(moodMessages[mood] || 'Mood set!');
  };

  return (
    <div className={`floating-sidebar ${sidebarClosed ? 'closed' : ''}`}>
      <div className="sidebar-trigger" onClick={toggleSidebar}>
        ⚙️
      </div>

      <div className="sidebar-header">
        <h3>Quick Tools</h3>
        <button className="sidebar-close" onClick={toggleSidebar}>×</button>
      </div>

      <div className="sidebar-body">
        <div className="sidebar-feature" onClick={showOrderHistory}>
          <span className="feature-icon">📊</span>
          <div className="feature-title">Order Analytics</div>
          <div className="feature-desc">View your ordering patterns</div>
          <div className="feature-value">{pastOrders.length} Orders</div>
          <div className="progress-bar">
            <div className="progress-fill" style={{ width: '75%' }}></div>
          </div>
        </div>

        <div className="sidebar-feature">
          <span className="feature-icon">🕰️</span>
          <div className="feature-title">Live Time</div>
          <div className="feature-desc">Current time & date</div>
          <div className="feature-value">
            {currentTime.toLocaleTimeString('en-US', {
              hour: '2-digit',
              minute: '2-digit',
              hour12: true
            })}
          </div>
          <div style={{ fontSize: '11px', color: '#666', marginTop: '3px' }}>
            {currentTime.toLocaleDateString('en-US', {
              weekday: 'long',
              month: 'short',
              day: 'numeric'
            })}
          </div>
        </div>

        <div className="sidebar-feature">
          <span className="feature-icon">🌡️</span>
          <div className="feature-title">Canteen Status</div>
          <div className="feature-desc">Current availability</div>
          <div className="feature-value" style={{ color: '#28a745' }}>Open</div>
          <div style={{ fontSize: '11px', color: '#666', marginTop: '3px' }}>Closes at 6:00 PM</div>
        </div>

        <div className="sidebar-feature">
          <span className="feature-icon">⚡</span>
          <div className="feature-title">Quick Order</div>
          <div className="feature-desc">Popular items</div>
          <div className="quick-order">
            <div className="quick-item" onClick={() => quickAddToCart(1)}>Veg Thali</div>
            <div className="quick-item" onClick={() => quickAddToCart(6)}>Chai</div>
            <div className="quick-item" onClick={() => quickAddToCart(2)}>Samosa</div>
            <div className="quick-item" onClick={() => quickAddToCart(3)}>Dosa</div>
          </div>
        </div>

        <div className="sidebar-feature">
          <span className="feature-icon">😊</span>
          <div className="feature-title">Mood Selector</div>
          <div className="feature-desc">How are you feeling?</div>
          <div className="mood-selector">
            <button 
              className={`mood-btn ${activeMood === 'happy' ? 'active' : ''}`} 
              onClick={() => setMood('happy')}
            >
              😊
            </button>
            <button 
              className={`mood-btn ${activeMood === 'hungry' ? 'active' : ''}`} 
              onClick={() => setMood('hungry')}
            >
              😋
            </button>
            <button 
              className={`mood-btn ${activeMood === 'tired' ? 'active' : ''}`} 
              onClick={() => setMood('tired')}
            >
              😴
            </button>
            <button 
              className={`mood-btn ${activeMood === 'excited' ? 'active' : ''}`} 
              onClick={() => setMood('excited')}
            >
              🤩
            </button>
          </div>
        </div>

        <div className="sidebar-feature" onClick={() => showToast('Feedback feature coming soon!')}>
          <span className="feature-icon">📝</span>
          <div className="feature-title">Quick Feedback</div>
          <div className="feature-desc">Rate your experience</div>
          <div style={{ marginTop: '8px' }}>
            <span style={{ color: '#ffc107', fontSize: '16px' }}>★★★★☆</span>
          </div>
        </div>
      </div>
    </div>
  );
}

export default FloatingSidebar;
